'use strict';

const ALLOWED_SCRIPT_PATHS = new Set([
  "scripts/client_credentials.js",
  "scripts/token_exchange.js",
  "scripts/introspect_token.js",
  "scripts/moa_local_exchange.js",
  "scripts/moa_feature_probe.js",
  "scripts/agent_info_register.js",
  "scripts/mtsso_configs.js"
]);

function resolveScriptModule(scriptRelativePath) {
  switch (scriptRelativePath) {
    case "scripts/client_credentials.js":
      return require("./scripts/client_credentials.js");
    case "scripts/token_exchange.js":
      return require("./scripts/token_exchange.js");
    case "scripts/introspect_token.js":
      return require("./scripts/introspect_token.js");
    case "scripts/moa_local_exchange.js":
      return require("./scripts/moa_local_exchange.js");
    case "scripts/moa_feature_probe.js":
      return require("./scripts/moa_feature_probe.js");
    case "scripts/agent_info_register.js":
      return require("./scripts/agent_info_register.js");
    case "scripts/mtsso_configs.js":
      return require("./scripts/mtsso_configs.js");
    default:
      return null;
  }
}

let invocationQueue = Promise.resolve();

function hasOwn(target, key) {
  return Object.prototype.hasOwnProperty.call(target, key);
}

function isNil(value) {
  return value === undefined || value === null;
}

function shouldSkipValue(value) {
  return isNil(value) || value === '';
}

function normalizeBooleanValue(value) {
  if (typeof value === 'boolean') {
    return value ? 'true' : 'false';
  }
  return String(value);
}

function normalizeRepeatableValue(value) {
  if (Array.isArray(value)) {
    return value;
  }
  return [value];
}

function resolveOptionValue(params, keys) {
  for (const key of keys) {
    if (hasOwn(params, key)) {
      return {
        found: true,
        value: params[key],
      };
    }
  }
  return {
    found: false,
    value: undefined,
  };
}

function appendOptionArgs(args, option, valueInfo) {
  if (!valueInfo.found) {
    return;
  }

  if (option.type === 'boolean_flag') {
    if (valueInfo.value) {
      args.push(option.flag);
    }
    return;
  }

  if (option.type === 'repeatable_value') {
    const values = normalizeRepeatableValue(valueInfo.value);
    for (const item of values) {
      if (shouldSkipValue(item)) {
        continue;
      }
      args.push(option.flag, String(item));
    }
    return;
  }

  if (option.type === 'boolean_value') {
    if (isNil(valueInfo.value)) {
      return;
    }
    args.push(option.flag, normalizeBooleanValue(valueInfo.value));
    return;
  }

  if (option.type === 'value') {
    if (shouldSkipValue(valueInfo.value)) {
      return;
    }
    args.push(option.flag, String(valueInfo.value));
  }
}

function buildArgs(params, optionSpecs) {
  const args = [];
  for (const option of optionSpecs) {
    const valueInfo = resolveOptionValue(params, option.keys || []);
    appendOptionArgs(args, option, valueInfo);
  }
  return args;
}

function parseResponseBody(stdoutText) {
  const trimmed = String(stdoutText || '').trim();
  if (!trimmed) {
    return {
      ok: false,
      value: null,
    };
  }

  try {
    return {
      ok: true,
      value: JSON.parse(trimmed),
    };
  } catch (_error) {
    return {
      ok: false,
      value: null,
    };
  }
}

function enqueueInvocation(task) {
  const next = invocationQueue.then(task, task);
  invocationQueue = next.then(() => undefined, () => undefined);
  return next;
}

function clearScriptModuleCache() {
  for (const modulePath of Object.keys(require.cache)) {
    const normalizedModulePath = String(modulePath).replace(/\\/g, '/');
    for (const scriptRelativePath of ALLOWED_SCRIPT_PATHS) {
      if (normalizedModulePath.endsWith('/' + scriptRelativePath)) {
        delete require.cache[modulePath];
        break;
      }
    }
  }
}

function resolveScriptMain(scriptRelativePath) {
  if (!ALLOWED_SCRIPT_PATHS.has(scriptRelativePath)) {
    throw new Error('Unknown API script mapping: ' + scriptRelativePath);
  }

  clearScriptModuleCache();
  const scriptPath = scriptRelativePath;
  const scriptModule = resolveScriptModule(scriptRelativePath);
  if (!scriptModule || typeof scriptModule.main !== 'function') {
    throw new Error('Script main is not available: ' + scriptRelativePath);
  }

  return {
    scriptPath,
    scriptMain: scriptModule.main,
  };
}

function applyRuntimeEnvOverrides(envOverrides) {
  if (!envOverrides || typeof envOverrides !== 'object') {
    return [];
  }

  const snapshots = [];
  for (const key of Object.keys(envOverrides)) {
    snapshots.push({
      key,
      hadOwn: hasOwn(process.env, key),
      value: process.env[key],
    });
    const overrideValue = envOverrides[key];
    if (overrideValue === undefined) {
      delete process.env[key];
      continue;
    }
    process.env[key] = String(overrideValue);
  }
  return snapshots;
}

function restoreRuntimeEnvOverrides(snapshots) {
  for (const entry of snapshots) {
    if (entry.hadOwn) {
      process.env[entry.key] = entry.value;
    } else {
      delete process.env[entry.key];
    }
  }
}

function captureWrite(chunks, chunk, encoding, callback) {
  let callbackFn = callback;
  let resolvedEncoding = encoding;

  if (typeof encoding === 'function') {
    callbackFn = encoding;
    resolvedEncoding = undefined;
  }

  if (Buffer.isBuffer(chunk)) {
    chunks.push(chunk.toString(typeof resolvedEncoding === 'string' ? resolvedEncoding : 'utf8'));
  } else {
    chunks.push(String(chunk ?? ''));
  }

  if (typeof callbackFn === 'function') {
    callbackFn();
  }

  return true;
}

async function invokeMainInProcess(options) {
  const scriptRelativePath = options.scriptRelativePath;
  const args = Array.isArray(options.args) ? options.args : [];
  const runtimeOptions = options.runtimeOptions && typeof options.runtimeOptions === 'object'
    ? options.runtimeOptions
    : {};

  const scriptInfo = resolveScriptMain(scriptRelativePath);
  const scriptMain = scriptInfo.scriptMain;
  const scriptPath = scriptInfo.scriptPath;

  const stdoutChunks = [];
  const stderrChunks = [];

  const originalArgv = process.argv;
  const originalWorkingDirectory = process.cwd();
  const originalStdoutWrite = process.stdout.write;
  const originalStderrWrite = process.stderr.write;
  const originalProcessExit = process.exit;

  const hasRuntimeCwd = !shouldSkipValue(runtimeOptions.cwd);
  let runtimeCwdApplied = false;
  let envSnapshots = [];

  let exitCode = 1;
  let signal = null;

  try {
    process.argv = [process.execPath, scriptPath, ...args];

    if (hasRuntimeCwd) {
      process.chdir(String(runtimeOptions.cwd));
      runtimeCwdApplied = true;
    }

    envSnapshots = applyRuntimeEnvOverrides(runtimeOptions.env);

    process.stdout.write = function patchedStdoutWrite(chunk, encoding, callback) {
      return captureWrite(stdoutChunks, chunk, encoding, callback);
    };

    process.stderr.write = function patchedStderrWrite(chunk, encoding, callback) {
      return captureWrite(stderrChunks, chunk, encoding, callback);
    };

    process.exit = function patchedProcessExit(code) {
      const processExitError = new Error('PROCESS_EXIT_SIGNAL');
      processExitError.__ssoProcessExit = true;
      processExitError.__ssoProcessExitCode = Number.isInteger(code) ? code : 1;
      throw processExitError;
    };

    const code = await scriptMain();
    exitCode = Number.isInteger(code) ? code : 1;
  } catch (error) {
    if (error && error.__ssoProcessExit) {
      exitCode = Number.isInteger(error.__ssoProcessExitCode) ? error.__ssoProcessExitCode : 1;
    } else {
      const message = error && error.message ? error.message : String(error);
      stderrChunks.push('\x1b[0;31m错误: ' + message + '\x1b[0m\n');
      exitCode = 1;
    }
  } finally {
    process.stdout.write = originalStdoutWrite;
    process.stderr.write = originalStderrWrite;
    process.exit = originalProcessExit;
    process.argv = originalArgv;
    restoreRuntimeEnvOverrides(envSnapshots);
    if (runtimeCwdApplied) {
      process.chdir(originalWorkingDirectory);
    }
  }

  return {
    exitCode,
    signal,
    stdout: stdoutChunks.join(''),
    stderr: stderrChunks.join(''),
    argv: args,
  };
}

function runCommand(options) {
  const scriptRelativePath = options.scriptRelativePath;
  const params = options.params && typeof options.params === 'object' ? options.params : {};
  const optionSpecs = Array.isArray(options.optionSpecs) ? options.optionSpecs : [];
  const runtimeOptions = options.runtimeOptions && typeof options.runtimeOptions === 'object'
    ? options.runtimeOptions
    : {};

  const args = buildArgs(params, optionSpecs);

  return enqueueInvocation(async () => {
    const execution = await invokeMainInProcess({
      scriptRelativePath,
      args,
      runtimeOptions,
    });

    const exitCode = Number.isInteger(execution.exitCode) ? execution.exitCode : 1;
    const responseBody = String(execution.stdout || '');
    const parsed = parseResponseBody(responseBody);

    return {
      ok: exitCode === 0,
      code: exitCode,
      exitCode,
      signal: execution.signal || null,
      argv: execution.argv || args,
      stdout: responseBody,
      stderr: String(execution.stderr || ''),
      responseBody,
      response: parsed.ok ? parsed.value : responseBody,
      responseJson: parsed.ok ? parsed.value : null,
    };
  });
}

module.exports = {
  runCommand,
};
